// CORRECTED UPSTREAM CODE - DATA VENTAS AGGREGATION WITH PERIOD FILTERING
// ✅ NEW: Automatic period detection based on majority transactions
// ✅ NEW: Filters all transactions (FC, NC, CR) by detected period
// ✅ FIXED: Only processes transactions from the correct period

// Get input data
const items = $input.all();

// Define the columns to process
const columns = [
  "Neto 21%", "IVA 21%", "Neto 10.5%", "IVA 10.5%", "Neto 27%", "IVA 27%",
  "Neto 0%", "IVA 0%", "Neto 2.5%", "IVA 2.5%", "Neto 5%", "IVA 5%",
  "Importe operaciones exportación", "Importe Exento", "Importe No Alcanzado",
  "Importe no gravado", "Importe Impuestos Internos", "Percepciones IIBB",
  "Percepciones IVA", "Otras Percepciones", "Otros regímenes especiales",
  "Total Comprobante"
];

// ========================================
// HELPER FUNCTION: Convert date to MM/YYYY
// ========================================
function convertirFechaPeriodo(fecha) {
  if (!fecha || fecha === "TOTALES") {
    return null;
  }

  // Case A: Excel Serial Number (e.g., 45870)
  if (typeof fecha === 'number') {
    const dateObj = new Date((fecha - 25569) * 86400 * 1000);
    const month = (dateObj.getUTCMonth() + 1).toString().padStart(2, '0');
    const year = dateObj.getUTCFullYear();
    return `${month}/${year}`;
  }

  // Case B: String format "DD/MM/YYYY"
  if (typeof fecha === 'string' && fecha.includes('/')) {
    const dateParts = fecha.split('/');
    if (dateParts.length === 3) {
      return `${dateParts[1]}/${dateParts[2]}`;
    }
  }

  return null;
}

// ========================================
// PASADA 1: Detect majority period
// ========================================
const periodCount = {};

items.forEach(item => {
  const data = item.json;
  const periodo = convertirFechaPeriodo(data.Fecha);

  if (periodo) {
    periodCount[periodo] = (periodCount[periodo] || 0) + 1;
  }
});

// Find the period with most transactions
let periodoMayoritario = null;
let maxCount = 0;

Object.keys(periodCount).forEach(periodo => {
  if (periodCount[periodo] > maxCount) {
    maxCount = periodCount[periodo];
    periodoMayoritario = periodo;
  }
});

// ========================================
// Initialize result object
// ========================================
const result = {
  "V-Periodo": periodoMayoritario || "",
  "V-Retenciones CR - Total": 0
};

// Initialize all columns (positive and negative) to 0
columns.forEach(col => {
  result[`V-${col} - Positivo`] = 0;
  result[`V-${col} - Negativo`] = 0;
});

// ========================================
// PASADA 2: Process only majority period
// ========================================
items.forEach(item => {
  const data = item.json;

  // Skip TOTALES row
  if (data.Fecha === "TOTALES") {
    return;
  }

  // Get period of this transaction
  const periodoTransaccion = convertirFechaPeriodo(data.Fecha);

  // 🔧 CRITICAL: Only process if transaction is from majority period
  if (periodoTransaccion !== periodoMayoritario) {
    return; // Skip transactions from other periods
  }

  const tc = data.TC;

  // Process each column
  columns.forEach(col => {
    const value = data[col] || 0;

    // FC/ND/CF/FE → Positivo (with Math.abs to ensure positive)
    if (["FC", "ND", "CF", "FE"].includes(tc)) {
      result[`V-${col} - Positivo`] += Math.abs(value);
    }

    // NC → Negativo (with Math.abs to ensure positive storage)
    if (tc === "NC") {
      result[`V-${col} - Negativo`] += Math.abs(value);
    }
  });

  // 🔧 CR (Constancia de Retención) - NOW FILTERED BY PERIOD
  if (tc === "CR") {
    const totalComprobante = data["Total Comprobante"] || 0;
    result["V-Retenciones CR - Total"] += Math.abs(totalComprobante);
  }
});

// Return single item
return [
  {
    json: result
  }
];

// 🚨 IMPLEMENTATION NOTES:
//
// 1. ✅ NEW: Two-pass algorithm
//    - PASS 1: Count transactions per period
//    - PASS 2: Process only majority period
//
// 2. ✅ NEW: convertirFechaPeriodo() helper function
//    - Handles Excel serial dates (e.g., 45870)
//    - Handles string dates (e.g., "28/07/2025")
//    - Returns MM/YYYY format
//
// 3. ✅ FIXED: Period filtering for ALL transaction types
//    - FC, ND, CF, FE: Only from majority period
//    - NC: Only from majority period
//    - CR: Only from majority period ← THIS WAS THE BUG
//
// 4. Example with your data:
//    INPUT (07/2025 file):
//      - Transactions with dates in 07/2025: 8 records
//      - CR with date 45836 (05/2025): 1 record ❌
//      - CR with date 45897 (08/2025): 1 record ❌
//      - CR with date 28/07/2025 (07/2025): 1 record ✅
//    
//    PERIOD COUNT:
//      { "07/2025": 8, "05/2025": 1, "08/2025": 1 }
//    
//    MAJORITY PERIOD: "07/2025" (8 transactions)
//    
//    OUTPUT:
//      - V-Periodo: "07/2025"
//      - V-Retenciones CR - Total: 800000 (only the 28/07/2025 CR)
//      - Other CR transactions IGNORED ✅
//
// 5. Edge cases handled:
//    - Mixed date formats (Excel serial + string)
//    - TOTALES row ignored
//    - Null/undefined dates ignored
//    - Automatic period detection (no manual input needed)

// Get input data
const items = $input.all();

// Define the columns to process
const columns = [
  "Neto 21%",
  "IVA 21%",
  "Neto 10.5%",
  "IVA 10.5%",
  "Neto 27%",
  "IVA 27%",
  "Neto 0%",
  "IVA 0%",
  "Neto 2.5%",
  "IVA 2.5%",
  "Neto 5%",
  "IVA 5%",
  "Importe Exento",
  "Importe No Alcanzado",
  "Importe no gravado",
  "Compras a exentos, monotributistas y otros",
  "Importe Impuestos Internos",
  "Percepciones IIBB",
  "Percepciones IVA",
  "Otras Percepciones",
  "Otros regímenes especiales",
  "Total Comprobante"
];

// Initialize result object with Periodo
const result = {
  "C-Periodo": ""
};

// Initialize all columns (positive and negative absolute) to 0 with C- prefix
columns.forEach(col => {
  result[`C-${col} - Positivo`] = 0;
  result[`C-${col} - Negativo`] = 0;
});

// Extract period from the first valid date
let periodExtracted = false;

// Process each item
items.forEach(item => {
  const data = item.json;

  // Skip the TOTALES row
  if (data.Fecha === "TOTALES") {
    return;
  }

  // --- DATE LOGIC FIX START ---
  // Extract period from first valid date
  if (!periodExtracted && data.Fecha) {

    // Case A: It is an Excel Serial Number (e.g., 45870)
    if (typeof data.Fecha === 'number') {
       // Convert Excel serial to JS Date (Excel starts 1900, JS starts 1970)
       // 25569 is the day offset, 86400 seconds/day, 1000 ms/second
       const dateObj = new Date((data.Fecha - 25569) * 86400 * 1000);

       // Add 1 to month because JS months are 0-indexed (0 = Jan, 11 = Dec)
       const month = (dateObj.getUTCMonth() + 1).toString().padStart(2, '0');
       const year = dateObj.getUTCFullYear();

       result["C-Periodo"] = `${month}/${year}`;
       periodExtracted = true;
    }
    // Case B: It is a String (e.g., "20/08/2025")
    else if (typeof data.Fecha === 'string' && data.Fecha.includes('/')) {
      const dateParts = data.Fecha.split('/');
      if (dateParts.length === 3) {
        result["C-Periodo"] = `${dateParts[1]}/${dateParts[2]}`; // MM/YYYY
        periodExtracted = true;
      }
    }
  }
  // --- DATE LOGIC FIX END ---

  // Process each column
  columns.forEach(col => {
    const value = data[col] || 0;

    // If value is positive, add to positive column
    if (value > 0) {
      result[`C-${col} - Positivo`] += value;
    }
    // If value is negative, add absolute value to negative column
    else if (value < 0) {
      result[`C-${col} - Negativo`] += Math.abs(value);
    }
  });
});

// Return single item with all columns split
return [
  {
    json: result
  }
];

// Check CUIT format from Input A (COMPRAS)
const items = $input.all();

items.forEach((item, index) => {
  if (index < 3) { // Check first 3 items
    console.log('CUIT:', item.json.CUIT);
    console.log('Type:', typeof item.json.CUIT);
    console.log('Length:', String(item.json.CUIT).length);
    console.log('---');
  }
});

return items;

// Loop through all input items
const results = $input.all().map(item => {
  return {
    json: {
      // Extract only the CUIT column
      "CUIT": item.json["CUIT"]
    }
  };
});

// Filter out rows where CUIT is undefined (e.g., the "TOTALES" row)
// to ensure you get a clean list of identifiers.
const cleanResults = results.filter(item => item.json["CUIT"] !== undefined);

return cleanResults;

// Check CUIT format from Input A (COMPRAS)
const items = $input.all();

items.forEach((item, index) => {
  if (index < 3) { // Check first 3 items
    console.log('CUIT:', item.json.CUIT);
    console.log('Type:', typeof item.json.CUIT);
    console.log('Length:', String(item.json.CUIT).length);
    console.log('---');
  }
});

return items;

// CORRECTED N8N JAVASCRIPT CODE - MAIN CALCULATION NODE
// This code matches Excel formulas exactly from Referencia_JSNode_V1_.xlsx
// ✅ UPDATED: Compras No Gravadas now ONLY includes 3 fields (Exento, No Alcanzado, No Gravado)
// ✅ UPDATED: NC Ventas and VAT now output as POSITIVE values (Removed *-1)

// Get input data
const items = $input.all();

// Merge all input items into a single object
let data = {};
items.forEach(item => {
    Object.assign(data, item.json);
});

// Helper function to safely get number values (default to 0)
const get = (key) => {
    const val = data[key];
    return typeof val === 'number' ? val : 0;
};

// --- PERIOD HANDLING ---
const periodStr = data["V-Periodo"] || "";
let periodDate = "";
if (periodStr) {
    periodDate = periodStr; 
}

// --- SALES CALCULATIONS (Ventas) ---
const v_neto_21_pos = get("V-Neto 21% - Positivo");
const v_neto_105_pos = get("V-Neto 10.5% - Positivo");
const v_neto_27_pos = get("V-Neto 27% - Positivo");
const v_iva_21_pos = get("V-IVA 21% - Positivo");
const v_iva_105_pos = get("V-IVA 10.5% - Positivo");
const v_iva_27_pos = get("V-IVA 27% - Positivo");

const v_neto_21_neg = get("V-Neto 21% - Negativo");
const v_neto_105_neg = get("V-Neto 10.5% - Negativo");
const v_neto_27_neg = get("V-Neto 27% - Negativo");
const v_iva_21_neg = get("V-IVA 21% - Negativo");
const v_iva_105_neg = get("V-IVA 10.5% - Negativo");
const v_iva_27_neg = get("V-IVA 27% - Negativo");

// --- PURCHASES CALCULATIONS (Compras) ---
const c_neto_21_pos = get("C-Neto 21% - Positivo");
const c_neto_105_pos = get("C-Neto 10.5% - Positivo");
const c_neto_27_pos = get("C-Neto 27% - Positivo");
const c_iva_21_pos = get("C-IVA 21% - Positivo");
const c_iva_105_pos = get("C-IVA 10.5% - Positivo");
const c_iva_27_pos = get("C-IVA 27% - Positivo");

const c_monotributo = get("C-Compras a exentos, monotributistas y otros - Positivo");

const c_neto_nc_total = 
    get("C-Neto 21% - Negativo") + get("C-Neto 10.5% - Negativo") + get("C-Neto 27% - Negativo") +
    get("C-Neto 0% - Negativo") + get("C-Neto 2.5% - Negativo") + get("C-Neto 5% - Negativo");

const c_iva_nc_total = 
    get("C-IVA 21% - Negativo") + get("C-IVA 10.5% - Negativo") + get("C-IVA 27% - Negativo") +
    get("C-IVA 0% - Negativo") + get("C-IVA 2.5% - Negativo") + get("C-IVA 5% - Negativo");

const c_perc_iva = get("C-Percepciones IVA - Positivo") - get("C-Percepciones IVA - Negativo");
const retenciones = 1 * get("V-Retenciones CR - Total");

// --- AGGREGATIONS & CORE CALCULATIONS ---
const total_ventas_netas = v_neto_21_pos + v_neto_105_pos + v_neto_27_pos;
const debito_t_gral = v_iva_21_pos + v_iva_105_pos + v_iva_27_pos;

const v_exento = get("V-Importe Exento - Positivo") - get("V-Importe Exento - Negativo");
const v_no_gravado = (get("V-Importe no gravado - Positivo") - get("V-Importe no gravado - Negativo")) + 
                     (get("V-Neto 0% - Positivo") - get("V-Neto 0% - Negativo"));
const v_no_alcanzado = get("V-Importe No Alcanzado - Positivo") - get("V-Importe No Alcanzado - Negativo");
const v_exportacion = get("V-Importe operaciones exportación - Positivo") - get("V-Importe operaciones exportación - Negativo");
const v_impuestos_internos = get("V-Importe Impuestos Internos - Positivo") - get("V-Importe Impuestos Internos - Negativo");
const v_perc_iibb = get("V-Percepciones IIBB - Positivo") - get("V-Percepciones IIBB - Negativo");
const v_perc_iva = get("V-Percepciones IVA - Positivo") - get("V-Percepciones IVA - Negativo");
const v_otras_perc = get("V-Otras Percepciones - Positivo") - get("V-Otras Percepciones - Negativo");
const v_regimenes_esp = get("V-Otros regímenes especiales - Positivo") - get("V-Otros regímenes especiales - Negativo");

const venta_exenta_ng = v_exento + v_no_gravado + v_no_alcanzado + v_exportacion + v_impuestos_internos + v_perc_iibb + v_perc_iva + v_otras_perc + v_regimenes_esp;

// 🔧 ADJUSTED: Compras No Gravadas (Excel: V4) - Sum of U, V, W only
const compras_no_gravadas = 
    (get("C-Importe Exento - Positivo") - get("C-Importe Exento - Negativo")) +             
    (get("C-Importe No Alcanzado - Positivo") - get("C-Importe No Alcanzado - Negativo")) + 
    (get("C-Importe no gravado - Positivo") - get("C-Importe no gravado - Negativo"));     

const total_credito = c_iva_21_pos + c_iva_105_pos + c_iva_27_pos;

// --- FISCAL CALCULATIONS ---
const total_debito_fiscal = debito_t_gral + c_iva_nc_total;
// total_credito_fiscal correctly adds the positive NC values from sales
const total_credito_fiscal = total_credito + v_iva_21_neg + v_iva_105_neg + v_iva_27_neg;
const total_ret_perc = c_perc_iva + retenciones;

const prev_saldo_1_parrafo = 0;
const prev_saldo_2_parrafo = 0;

const saldo_1_parrafo = prev_saldo_1_parrafo < 0 ? 
    (total_credito_fiscal - total_debito_fiscal) : 
    (total_credito_fiscal - total_debito_fiscal + prev_saldo_1_parrafo);

const saldo_2_parrafo = prev_saldo_2_parrafo < 0 ?
    (saldo_1_parrafo < 0 ? saldo_1_parrafo + total_ret_perc : total_ret_perc) :
    (saldo_1_parrafo < 0 ? prev_saldo_2_parrafo + saldo_1_parrafo + total_ret_perc : total_ret_perc + prev_saldo_2_parrafo);

const saldo_a_pagar = saldo_2_parrafo < 0 ? saldo_2_parrafo : 0;

// --- OUTPUT CONSTRUCTION ---
const result = {
    "Periodo": periodDate,
    "Cliente": data["Cliente"] || "",
    "Venta Neta 21%": v_neto_21_pos,
    "Venta Neta 10.5%": v_neto_105_pos,
    "Venta Neta 27%": v_neto_27_pos,
    "Total Ventas Netas": total_ventas_netas,
    "Débito Ventas 21%": v_iva_21_pos,
    "Débito Ventas 10.5%": v_iva_105_pos,
    "Débito Ventas 27%": v_iva_27_pos,
    "Debito T. Gral.": debito_t_gral,
    "V-Exento": v_exento,
    "V-No Gravado": v_no_gravado,
    "V-No Alcanzado": v_no_alcanzado,
    "V-Exportación": v_exportacion,
    "V-Impuestos Internos": v_impuestos_internos,
    "V-Percepciones IIBB": v_perc_iibb,
    "V-Percepciones IVA": v_perc_iva,
    "V-Otras Percepciones": v_otras_perc,
    "V-Regímenes Especiales": v_regimenes_esp,
    "Total V-Otros NG/NA/Exento": venta_exenta_ng,
    "Neto NC Compras": c_neto_nc_total,
    "Débito NC Compras": c_iva_nc_total,
    "Compras No Gravadas": compras_no_gravadas,
    "Compras Monotributo": c_monotributo,
    "IVA No Computable": 0,
    "Compras Neto 21%": c_neto_21_pos,
    "Compras Neto 10.5%": c_neto_105_pos,
    "Compras Neto 27%": c_neto_27_pos,
    "IVA CF 21%": c_iva_21_pos,
    "IVA CF 10.5%": c_iva_105_pos,
    "IVA CF 27%": c_iva_27_pos,
    "Total Crédito": total_credito,

    // 🔧 Sales - Credit Notes (Outputs as positive values for report clarity)
    "NC Ventas Neto 21%": v_neto_21_neg,
    "NC Ventas Neto 10.5%": v_neto_105_neg,
    "NC Ventas Neto 27%": v_neto_27_neg,
    "CF NC Ventas 21%": v_iva_21_neg,
    "CF NC Ventas 10.5%": v_iva_105_neg,
    "CF NC Ventas 27%": v_iva_27_neg,

    "Percepciones": c_perc_iva,
    "Retenciones": retenciones,
    "Total Débito Fiscal": total_debito_fiscal,
    "Total Crédito Fiscal": total_credito_fiscal,
    "Total Retenciones y Percecpiones": total_ret_perc,
    "Saldo 1 Párrafo": saldo_1_parrafo,
    "Saldo 2 Párrafo": saldo_2_parrafo,
    "Saldo a pagar": saldo_a_pagar
};

return [{ json: result }];

